/**
 * HEADHUNTER AGENT - GATEKEEPER CODE NODE
 * Implements Anti-Avatar filtering (Section 2.3) and Compact State logic (Section 4.3)
 */

const ACUTE_CARE_KEYWORDS = [
  'trauma', 'er', 'emergency room', 'icu', 'intensive care',
  'or', 'operating room', 'med-surg', 'medsurg', 'medical surgical',
  'ccu', 'cardiac care', 'nicu', 'picu', 'pacu', 'cath lab'
];

const CLINIC_OUTPATIENT_KEYWORDS = [
  'dialysis manager', 'clinic supervisor', 'school nurse',
  'outpatient', 'ambulatory', 'urgent care', 'physician office'
];

const ACADEMIC_RESEARCH_KEYWORDS = [
  'professor', 'faculty', 'research coordinator', 'instructor', 'academic'
];

const LTC_CONTEXT_KEYWORDS = [
  'snf', 'skilled nursing', 'nursing home', 'long term care', 'ltc',
  'post-acute', 'rehab', 'subacute', 'assisted living', 'geriatric'
];

const COMPACT_STATES = [
  'AL', 'AZ', 'AR', 'CO', 'DE', 'FL', 'GA', 'ID', 'IN', 'IA',
  'KS', 'KY', 'LA', 'ME', 'MD', 'MS', 'MO', 'MT', 'NE', 'NH',
  'NJ', 'NM', 'NC', 'ND', 'OH', 'OK', 'SC', 'SD', 'TN', 'TX',
  'UT', 'VA', 'VT', 'WV', 'WI', 'WY'
];

const PRIORITY_DEPLOY_STATES = ['TX', 'FL', 'TN', 'VA', 'GA', 'NC', 'AZ'];

const INTERIM_FIXER_KEYWORDS = [
  'interim', 'travel', 'contract', 'consultant', 'locum', 'temporary', 'agency'
];

const TURNAROUND_SPECIALIST_KEYWORDS = [
  'survey', 'plan of correction', 'poc', 'ij', 'immediate jeopardy',
  'turnaround', 'regulatory compliance', 'mock survey', 'qapi'
];

const MDS_SPECIALIST_KEYWORDS = [
  'mds', 'mds coordinator', 'rac-ct', 'rai coordinator', 'pdpm', 'casemix'
];

const CORPORATE_SNF_EMPLOYERS = [
  'genesis', 'sava', 'ensign', 'golden living', 'promedica', 'signature healthcare'
];

function containsKeyword(text, keywords) {
  if (!text) return false;
  const lowerText = text.toLowerCase();
  return keywords.some(kw => lowerText.includes(kw.toLowerCase()));
}

function extractState(location) {
  if (!location) return null;
  const match = location.match(/\b([A-Z]{2})\b/);
  return match ? match[1] : null;
}

const results = [];

for (const item of $input.all()) {
  const c = item.json;
  const searchText = [c.title, c.headline, c.description, c.summary, c.skills].join(' ').toLowerCase();
  const employer = (c.company || '').toLowerCase();
  const state = extractState(c.location || '');

  let qualified = true;
  let disqualifyReason = null;
  const hasLTCContext = containsKeyword(searchText, LTC_CONTEXT_KEYWORDS);

  if (containsKeyword(searchText, ACUTE_CARE_KEYWORDS) && !hasLTCContext) {
    qualified = false;
    disqualifyReason = 'Acute care without SNF context';
  }
  if (qualified && containsKeyword(searchText, CLINIC_OUTPATIENT_KEYWORDS)) {
    qualified = false;
    disqualifyReason = 'Clinic/Outpatient role';
  }
  if (qualified && containsKeyword(searchText, ACADEMIC_RESEARCH_KEYWORDS)) {
    qualified = false;
    disqualifyReason = 'Academic/Research role';
  }

  const deployable = state && COMPACT_STATES.includes(state);
  const priorityDeploy = state && PRIORITY_DEPLOY_STATES.includes(state);

  let avatarType = 'UNCLASSIFIED';
  let priority = 'STANDARD';

  if (qualified) {
    const isInterim = containsKeyword(searchText, INTERIM_FIXER_KEYWORDS);
    const isTurnaround = containsKeyword(searchText, TURNAROUND_SPECIALIST_KEYWORDS);
    const isMDS = containsKeyword(searchText, MDS_SPECIALIST_KEYWORDS);
    const isCorporate = containsKeyword(employer, CORPORATE_SNF_EMPLOYERS);

    if (isTurnaround && isInterim) {
      avatarType = 'TURNAROUND_SPECIALIST';
      priority = 'HIGH';
    } else if (isMDS) {
      avatarType = 'MDS_SPECIALIST';
      priority = 'HIGH';
    } else if (isInterim) {
      avatarType = 'INTERIM_FIXER';
      priority = 'STANDARD';
    } else if (!isInterim && isCorporate) {
      avatarType = 'PASSIVE_BURNOUT';
      priority = 'MEDIUM';
    }
  }

  results.push({
    json: {
      ...c,
      qualified,
      disqualifyReason,
      deployable,
      priorityDeploy,
      candidateState: state,
      avatarType,
      priority,
      processedAt: new Date().toISOString()
    }
  });
}

return results;
